'use strict';
// A fake of the Playwright API surface used by base/shared/browser-harness.mjs and the test scenario
// scripts. Nothing is rendered: pages come from a site description, screenshots are small solid PNGs
// and page.evaluate runs the function in Node with a fake document and canvas.
//
// Environment:
//   FAKE_PW_SITE          JSON text or a path to a JSON file: { "/path": page, ... }, a page being
//                         { status, title, text: [], selectors: [], links: {text: path}, color: [r,g,b,a],
//                           dots: [[x, y, [r,g,b,a]]], console: [text | {type, text}], pageErrors: [text],
//                           responses: [{status, url, method}], failedRequests: [{url, errorText}],
//                           gotoError, dom: {scrollWidth, elements: [...], images: [...]} }
//   FAKE_PW_LOG           a file to append one JSON line per browser event to (launch, close, goto, ...)
//   FAKE_PW_LAUNCH_ERROR  make launchServer fail with this message
//   FAKE_PW_NO_PROCESS    do not start the stand-in browser process
//
// Screenshots are ceil(width / 40) x ceil(height / 40) pixels of the page color.

const fs = require('node:fs');
const path = require('node:path');
const { spawn } = require('node:child_process');
const png = require('./png.js');

const SCALE = 40;
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function loadSite() {
  const raw = process.env.FAKE_PW_SITE;
  if (!raw) return {};
  return JSON.parse(raw.trim().startsWith('{') ? raw : fs.readFileSync(raw, 'utf8'));
}

function log(event, data = {}) {
  if (!process.env.FAKE_PW_LOG) return;
  const record = { event, t: Date.now(), node: process.pid, scenario: process.env.BT_SCENARIO ?? null, ...data };
  fs.appendFileSync(process.env.FAKE_PW_LOG, JSON.stringify(record) + '\n');
}

function alive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

function timeoutError(what, ms) {
  return new Error(`${what}: Timeout ${ms}ms exceeded.\nCall log:\n  - waiting`);
}

class Locator {
  constructor(page, description, matches, name) {
    this._page = page;
    this._description = description;
    this._matches = matches;
    this._name = name;
  }

  first() {
    return this;
  }

  async waitFor({ state = 'visible', timeout } = {}) {
    const ms = timeout ?? this._page._timeout;
    const present = this._matches();
    if (present === (state === 'visible' || state === 'attached')) return;
    await delay(Math.min(ms, 20));
    throw timeoutError(`locator.waitFor(${this._description}, ${state})`, ms);
  }

  async click() {
    if (!this._matches()) throw timeoutError(`locator.click(${this._description})`, this._page._timeout);
    const target = (this._page._def.links || {})[this._name];
    if (target) await this._page.goto(target);
  }

  async isVisible() {
    return this._matches();
  }

  async count() {
    return this._matches() ? 1 : 0;
  }

  async textContent() {
    return this._matches() ? this._name : null;
  }
}

class Emitter {
  constructor() {
    this._handlers = {};
  }

  on(event, handler) {
    (this._handlers[event] ??= []).push(handler);
    return this;
  }

  _emit(event, value) {
    for (const handler of this._handlers[event] ?? []) handler(value);
  }
}

function element(spec, tag = 'div') {
  const style = { overflowX: spec.overflowX ?? 'visible', textOverflow: spec.textOverflow ?? 'clip' };
  return {
    tagName: (spec.tag ?? tag).toUpperCase(),
    id: spec.id ?? '',
    className: spec.className ?? '',
    innerText: spec.text ?? '',
    children: (spec.children ?? []).map((child) => element(child)),
    childNodes: spec.text ? [{ nodeType: 3, textContent: spec.text }] : [],
    scrollWidth: spec.scrollWidth ?? 0,
    clientWidth: spec.clientWidth ?? 0,
    complete: spec.complete ?? true,
    naturalWidth: spec.naturalWidth ?? 100,
    __style: style,
    getAttribute: (name) => (spec.attrs ?? {})[name] ?? null,
    getBoundingClientRect: () => ({ width: spec.width ?? 10, right: spec.right ?? 10 }),
  };
}

function flatten(elements) {
  return elements.flatMap((el) => [el, ...flatten(el.children)]);
}

// The canvas API the harness uses to compare screenshots.
class FakeContext2D {
  constructor(canvas) {
    this.canvas = canvas;
    this.data = new Uint8ClampedArray(canvas.width * canvas.height * 4);
  }

  drawImage(image) {
    this.data.set(image.data.subarray(0, this.data.length));
  }

  clearRect() {
    this.data.fill(0);
  }

  getImageData() {
    return { width: this.canvas.width, height: this.canvas.height, data: new Uint8ClampedArray(this.data) };
  }

  putImageData(image) {
    this.data.set(image.data);
  }
}

class FakeOffscreenCanvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this._context = new FakeContext2D(this);
  }

  getContext() {
    return this._context;
  }

  async convertToBlob({ type = 'image/png' } = {}) {
    return new Blob([png.encode(this.width, this.height, new Uint8Array(this._context.data))], { type });
  }
}

async function fakeCreateImageBitmap(blob) {
  return png.decode(Buffer.from(await blob.arrayBuffer()));
}

class Page extends Emitter {
  constructor(context) {
    super();
    this._context = context;
    this._viewport = { ...context._viewport };
    this._url = 'about:blank';
    this._def = {};
    this._timeout = 30000;
    this._closed = false;
  }

  setDefaultTimeout(ms) {
    this._timeout = ms;
    log('setDefaultTimeout', { ms });
  }

  url() {
    return this._url;
  }

  async title() {
    return this._def.title ?? '';
  }

  viewportSize() {
    return { ...this._viewport };
  }

  async setViewportSize(size) {
    this._viewport = { width: size.width, height: size.height };
    log('setViewportSize', this._viewport);
  }

  async goto(target) {
    const base = this._context._options.baseURL;
    const resolved = new URL(target, base || undefined);
    const site = loadSite();
    const def = site[resolved.pathname] ?? { status: 404 };
    log('goto', { url: resolved.toString() });
    if (def.gotoError) throw new Error(`page.goto: ${def.gotoError}\nCall log:\n  - navigating to "${resolved}"`);
    this._url = resolved.toString();
    this._def = def;
    const response = (status, url, method = 'GET') => ({
      status: () => status, url: () => url, request: () => ({ method: () => method, url: () => url }),
    });
    const main = response(def.status ?? 200, this._url);
    this._emit('response', main);
    for (const r of def.responses ?? []) this._emit('response', response(r.status, new URL(r.url, resolved).toString(), r.method));
    for (const c of def.console ?? []) {
      const msg = typeof c === 'string' ? { type: 'error', text: c } : c;
      this._emit('console', { type: () => msg.type, text: () => msg.text });
    }
    for (const text of def.pageErrors ?? []) this._emit('pageerror', new Error(text));
    for (const r of def.failedRequests ?? []) {
      const url = new URL(r.url, resolved).toString();
      this._emit('requestfailed', { url: () => url, failure: () => ({ errorText: r.errorText }) });
    }
    return main;
  }

  async reload() {
    return this.goto(this._url);
  }

  async waitForTimeout(ms) {
    await delay(ms);
  }

  getByText(text) {
    return new Locator(this, `text=${text}`, () => (this._def.text ?? []).some((t) => t.includes(text)), text);
  }

  getByRole(role, { name } = {}) {
    return new Locator(this, `role=${role}[name=${name}]`, () => (this._def.text ?? []).includes(name), name);
  }

  locator(selector) {
    return new Locator(this, selector, () => (this._def.selectors ?? []).includes(selector), selector);
  }

  async screenshot(options = {}) {
    if (this._def.screenshotError) throw new Error(this._def.screenshotError);
    const width = Math.ceil(this._viewport.width / SCALE);
    const height = Math.ceil(this._viewport.height / SCALE);
    const buffer = png.solid(width, height, this._def.color ?? [255, 255, 255, 255], this._def.dots ?? []);
    if (options.path) {
      fs.mkdirSync(path.dirname(options.path), { recursive: true });
      fs.writeFileSync(options.path, buffer);
    }
    log('screenshot', { path: options.path ?? null, width, height, fullPage: options.fullPage ?? false });
    return buffer;
  }

  _document() {
    const dom = this._def.dom ?? {};
    const all = flatten((dom.elements ?? []).map((spec) => element(spec)));
    const scrolling = { clientWidth: this._viewport.width, scrollWidth: dom.scrollWidth ?? this._viewport.width };
    return {
      title: this._def.title ?? '',
      scrollingElement: scrolling,
      documentElement: scrolling,
      body: { querySelectorAll: () => all },
      images: (dom.images ?? []).map((spec) => element(spec, 'img')),
    };
  }

  // Runs the function in Node with the browser globals it may use, and returns a JSON copy of its value.
  async evaluate(fn, arg) {
    if (this._def.evaluateError) throw new Error(this._def.evaluateError);
    const globals = {
      document: this._document(),
      getComputedStyle: (el) => el.__style,
      requestAnimationFrame: (callback) => setTimeout(() => callback(Date.now()), 0),
      createImageBitmap: fakeCreateImageBitmap,
      OffscreenCanvas: FakeOffscreenCanvas,
    };
    const saved = {};
    for (const [key, value] of Object.entries(globals)) {
      saved[key] = Object.getOwnPropertyDescriptor(globalThis, key);
      globalThis[key] = value;
    }
    try {
      const value = await (typeof fn === 'function' ? fn(arg) : (0, eval)(fn));
      return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
    } finally {
      for (const [key, descriptor] of Object.entries(saved)) {
        if (descriptor) Object.defineProperty(globalThis, key, descriptor);
        else delete globalThis[key];
      }
    }
  }

  async close() {
    this._closed = true;
  }
}

class Context {
  constructor(browser, options = {}) {
    this._browser = browser;
    this._options = options;
    this._viewport = options.viewport ?? { width: 1280, height: 720 };
    this._pages = [];
  }

  async newPage() {
    const page = new Page(this);
    this._pages.push(page);
    return page;
  }

  pages() {
    return [...this._pages];
  }

  async close() {
    for (const page of this._pages) await page.close();
    log('contextClose');
  }
}

class Browser {
  constructor(server) {
    this._server = server;
    this._contexts = [];
  }

  async newContext(options = {}) {
    const { storageState, ...rest } = options;
    log('newContext', { options: rest });
    const context = new Context(this, options);
    this._contexts.push(context);
    return context;
  }

  async newPage(options = {}) {
    const context = await this.newContext(options);
    return context.newPage();
  }

  contexts() {
    return [...this._contexts];
  }

  async close() {
    log('browserClose');
  }
}

class BrowserServer {
  constructor(name, options) {
    this._name = name;
    this._options = options;
    this._child = null;
    if (!process.env.FAKE_PW_NO_PROCESS) {
      // A detached stand-in process whose command line names the browser, like a real browser server's.
      this._child = spawn(process.execPath, ['-e', 'setInterval(() => {}, 1e6)', `fake-${name}-browser`], {
        detached: process.platform !== 'win32', stdio: 'ignore',
      });
      this._child.unref();
    }
  }

  process() {
    return { pid: this._child ? this._child.pid : process.pid };
  }

  wsEndpoint() {
    return `ws://fake-${this._name}/${this.process().pid}`;
  }

  async close() {
    log('close', { browser: this._name, pid: this.process().pid });
    if (!this._child) return;
    try {
      process.kill(this._child.pid, 'SIGTERM');
    } catch {
      return;
    }
    for (let i = 0; i < 100 && this._child.exitCode === null && this._child.signalCode === null; i++) await delay(10);
  }
}

function browserType(name) {
  let server = null;
  return {
    name: () => name,
    async launchServer(options = {}) {
      if (process.env.FAKE_PW_LAUNCH_ERROR) throw new Error(process.env.FAKE_PW_LAUNCH_ERROR);
      server = new BrowserServer(name, options);
      log('launch', { browser: name, headless: options.headless ?? null, pid: server.process().pid });
      return server;
    },
    async connect(endpoint) {
      if (!server || endpoint !== server.wsEndpoint()) throw new Error(`cannot connect to ${endpoint}`);
      return new Browser(server);
    },
    async launch(options = {}) {
      const s = await this.launchServer(options);
      const browser = new Browser(s);
      const close = browser.close.bind(browser);
      browser.close = async () => {
        await close();
        await s.close();
      };
      return browser;
    },
  };
}

module.exports = {
  chromium: browserType('chromium'),
  firefox: browserType('firefox'),
  webkit: browserType('webkit'),
  __fake: true,
  __alive: alive,
};
